'use client';

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { getSiteData } from '@/data/siteData';
import { ServiceModal, ServiceModalItem } from '@/components/ServiceModal';
import { ArrowUpRight, Clock, Star, Map, Compass, Palmtree, Car } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';

interface ServicesListingProps {
    locale: string;
}

type SiteDataset = ReturnType<typeof getSiteData>;

const categories = [
    {
        id: 'tours',
        label: 'Cultural Tours',
        icon: Map,
        route: 'tours',
        data: (sd: SiteDataset) => sd.tours
    },
    {
        id: 'activities',
        label: 'Adventures',
        icon: Compass,
        route: 'activities',
        data: (sd: SiteDataset) => {
            const experiences = sd.activities.experiences || [];
            const grouped = experiences.reduce((acc: any, curr: any) => {
                const type = curr.type;
                if (!acc[type]) {
                    acc[type] = {
                        ...curr,
                        id: curr.type,
                    };
                }
                if (curr.price < acc[type].price) {
                    acc[type].price = curr.price;
                }
                return acc;
            }, {});
            return Object.values(grouped);
        }
    },
    {
        id: 'packages',
        label: 'Curated Packs',
        icon: Palmtree,
        route: 'packages',
        data: (sd: SiteDataset) => sd.packages
    },
    {
        id: 'transport',
        label: 'Transport',
        icon: Car,
        route: 'transport',
        data: (sd: SiteDataset) => sd.transport
    },
];

export const ServicesListing = ({ locale }: ServicesListingProps) => {
    const t = useTranslations('ServicesPage');
    const tCommon = useTranslations('Common');
    const [modalItem, setModalItem] = useState<ServiceModalItem | null>(null);
    const [modalCategory, setModalCategory] = useState<string>('services');
    const [modalLabel, setModalLabel] = useState<string | undefined>(undefined);

    const openModal = (item: any, categoryId: string, categoryLabel: string) => {
        setModalCategory(categoryId);
        setModalLabel(categoryLabel);
        setModalItem(item as ServiceModalItem);
    };

    const renderPrice = (item: any, categoryId: string) => {
        const perPerson = tCommon('perPerson');
        if (categoryId === 'tours' && item.pricing && item.pricing[0]) {
            const p = item.pricing[0] as any;
            return p.totalPrice ? `${p.totalPrice}€` : `€${p.pricePerPerson} ${perPerson}`;
        }
        if (categoryId === 'packages' || categoryId === 'activities') {
            return item.price ? `${item.price}€` : t('onRequest');
        }
        return t('onRequest');
    };

    return (
        <div className="min-h-screen bg-[#FDFBF7] font-poppins text-neutral-dark">
            {/* Hero Section */}
            <div className="relative h-[60vh] min-h-[500px] w-full overflow-hidden flex items-center justify-center">
                <div className="absolute inset-0" aria-hidden="true">
                    <Image
                        src="/images/hero-marrakech.jpg"
                        alt=""
                        fill
                        sizes="100vw"
                        className="object-cover"
                    />
                </div>
                <div className="absolute inset-0 bg-black/50"></div>
                <div className="relative z-10 container mx-auto px-4 text-center">
                    <motion.div
                        initial={{ opacity: 0, y: 30 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.8 }}
                    >
                        <span className="block font-poppins font-semibold text-primary text-xl italic mb-4">
                            {t('tag')}
                        </span>
                        <h1 className="text-5xl md:text-7xl font-bold font-poppins text-white mb-6 leading-tight">
                            {t('titlePart1')} <span className="text-primary-light">{t('titlePart2')}</span>
                        </h1>
                        <p className="text-xl text-gray-200 max-w-2xl mx-auto font-light leading-relaxed">
                            {t('subtitle')}
                        </p>
                    </motion.div>
                </div>
            </div>

            {/* Services Sections */}
            <div className="container mx-auto px-4 py-16">
                {categories.map((category, catIdx) => {
                    const items = category.data(getSiteData(locale));
                    if (!items || items.length === 0) return null;

                    return (
                        <div key={category.id} className="mb-20">
                            {/* Category Header */}
                            <div className="flex items-center justify-between mb-8">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center">
                                        <category.icon className="w-6 h-6 text-primary" />
                                    </div>
                                    <div>
                                        <h2 className="text-3xl font-bold font-poppins text-neutral-dark">
                                            {t(category.id === 'tours' ? 'culturalTours' : category.id === 'activities' ? 'adventures' : category.id === 'packages' ? 'curatedPacks' : 'transport')}
                                        </h2>
                                        <p className="text-gray-500 text-sm">
                                            {items.length} {items.length === 1 ? t('option') : t('options')} {t('available')}
                                        </p>
                                    </div>
                                </div>
                                <Link
                                    href={`/${locale}/${category.route}`}
                                    className="text-primary font-medium hover:underline flex items-center gap-2"
                                >
                                    {t('viewAll')} <ArrowUpRight className="w-4 h-4" />
                                </Link>
                            </div>

                            {/* Items Grid */}
                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                                {items.slice(0, 4).map((item: any, idx: number) => (
                                    <motion.div
                                        key={item.id}
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: (catIdx * 0.1) + (idx * 0.05) }}
                                        className="group"
                                    >
                                        <div className="bg-white rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 overflow-hidden flex flex-col md:flex-row h-auto md:h-[280px] border border-neutral-100 hover:-translate-y-1">
                                            {/* Image Section */}
                                            <div className="md:w-2/5 relative h-48 md:h-full overflow-hidden">
                                                <Image
                                                    src={item.image || '/images/hero-marrakech.jpg'}
                                                    alt={item.name || item.type || ''}
                                                    fill
                                                    sizes="(max-width: 768px) 100vw, 40vw"
                                                    className="object-cover transition-transform duration-700 group-hover:scale-110"
                                                />
                                                <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-md text-xs font-bold uppercase tracking-wider text-neutral-dark shadow-sm">
                                                    {t(category.id === 'tours' ? 'culturalTours' : category.id === 'activities' ? 'adventures' : category.id === 'packages' ? 'curatedPacks' : 'transport')}
                                                </div>
                                            </div>

                                            {/* Content Section */}
                                            <div className="md:w-3/5 p-6 flex flex-col justify-between">
                                                <div>
                                                    <div className="flex justify-between items-start mb-2">
                                                        <div className="flex items-center gap-2 text-gray-500 text-xs font-semibold uppercase tracking-wider">
                                                            <Clock className="w-3 h-3 text-primary" />
                                                            <span>
                                                                {category.id === 'tours' && item.duration ? t(`duration_${item.duration}`) :
                                                                    category.id === 'activities' ? t('duration_2_hours') :
                                                                        category.id === 'packages' ? t('duration_4_hours') : t('flexible')}
                                                            </span>
                                                        </div>
                                                    </div>

                                                    <h3 className="text-xl font-bold font-poppins text-neutral-dark mb-2 leading-tight group-hover:text-primary transition-colors uppercase">
                                                        {item.name || item.type}
                                                    </h3>

                                                    <p className="text-gray-500 text-sm leading-relaxed line-clamp-2">
                                                        {item.desc || item.description}
                                                    </p>
                                                </div>

                                                <div className="pt-4 mt-3 border-t border-neutral-100 flex flex-col sm:flex-row sm:items-center justify-between gap-4 sm:gap-2">
                                                    <div>
                                                        <p className="text-xs text-gray-400 font-medium mb-0.5">
                                                            {category.id === 'transport' ? t('price') : t('startingFrom')}
                                                        </p>
                                                        <p className="text-xl font-bold text-primary">{renderPrice(item, category.id)}</p>
                                                    </div>

                                                    <div className="flex items-center gap-2 w-full sm:w-auto">
                                                        <Link
                                                            href={`/${locale}/${category.route}/${item.id}`}
                                                            className="flex-1 sm:flex-none justify-center px-4 py-2 rounded-full bg-neutral-100 text-neutral-dark font-medium text-sm hover:bg-neutral-200 transition-all flex items-center gap-2"
                                                        >
                                                            {t('details')} <ArrowUpRight className="w-4 h-4" />
                                                        </Link>
                                                        <button
                                                            className="flex-1 sm:flex-none justify-center px-4 py-2 rounded-full bg-[#FDC82F] text-[#1A1A1A] font-bold text-sm hover:bg-[#e6b528] transition-all flex items-center gap-2 shadow-sm"
                                                            onClick={(e) => { e.stopPropagation(); openModal(item, category.id, category.label); }}
                                                        >
                                                            {t('quickView')}
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* ── Creative Modal ── */}
            <ServiceModal
                item={modalItem}
                category={modalCategory}
                locale={locale}
                label={modalLabel}
                onClose={() => setModalItem(null)}
            />
        </div>
    );
};
